-- Distribuidores
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D1'), 'Lácteos Ramírez Hnos.', 'Empresa familiar fundada en 1994 por los hermanos Gustavo y Daniel Ramírez. Distribuimos lácteos, quesos y fiambres a almacenes, autoservicios y cantinas del oeste de Montevideo, con cadena de frío propia. Repartimos de lunes a sábado en la mañana.', 'La Teja, Belvedere, Nuevo París, Tres Ombúes y Paso Molino', 'Av. Carlos María Ramírez, La Teja, Montevideo', true, date_trunc('day', NOW()) - INTERVAL '190 days' + TIME '11:00', '/uploads/demo/logos/lacteos-ramirez-hnos.svg', -34.8595228, -56.2279776) RETURNING id) INSERT INTO _seed_ids SELECT 'D1', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D2'), 'Carnes Don Aurelio', 'Más de 30 años abasteciendo a carnicerías, rotiserías y parrillas de la zona oeste. Cortes vacunos, cerdo, pollo y chacinados con trazabilidad y entrega refrigerada. Reparto martes, jueves y sábados.', 'Cerro, Casabó, La Paloma, Paso de la Arena, Santa Catalina y Nuevo París', 'Camino Cibils, Cerro Oeste, Montevideo', true, date_trunc('day', NOW()) - INTERVAL '194 days' + TIME '11:00', '/uploads/demo/logos/carnes-don-aurelio.svg', -34.8753826, -56.267762) RETURNING id) INSERT INTO _seed_ids SELECT 'D2', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D3'), 'Frutihortícola Olivera', 'Trabajamos directo con productores de Melilla y del Mercado Agrícola. Frutas y verduras de estación para fruterías, almacenes y comedores, seleccionadas cada madrugada. Entregas de lunes a viernes antes del mediodía.', 'Melilla, Colón, Lezica, Peñarol y Sayago', 'Camino Melilla, Melilla, Montevideo', true, date_trunc('day', NOW()) - INTERVAL '192 days' + TIME '11:00', '/uploads/demo/logos/frutihorticola-olivera.svg', -34.7676, -56.269) RETURNING id) INSERT INTO _seed_ids SELECT 'D3', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D4'), 'Panificadora La Espiga del Prado', 'Panadería de barrio desde 1987 que hoy abastece a almacenes, cafeterías y kioscos del Prado y alrededores. Pan del día, bizcochos, galletería y panificados envasados. Reparto diario, también los domingos de mañana.', 'Prado, Atahualpa, Capurro, Belvedere y Aires Puros', 'Av. Millán, Atahualpa (Prado), Montevideo', true, date_trunc('day', NOW()) - INTERVAL '189 days' + TIME '11:00', '/uploads/demo/logos/panificadora-la-espiga-del-prado.svg', -34.8624389, -56.1932499) RETURNING id) INSERT INTO _seed_ids SELECT 'D4', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D5'), 'Bebidas Costa Este', 'Distribuidor de bebidas con y sin alcohol para comercios, restoranes y paradores de la Costa de Oro. Aguas, refrescos, cervezas, vinos y jugos con entrega en cajones y packs cerrados. Reparto de lunes a sábado, y todos los días en temporada.', 'Ciudad de la Costa, Paso Carrasco, Carrasco y Costa de Oro hasta Atlántida', 'Av. Ing. Luis Giannattasio km 20,200, Ciudad de la Costa, Canelones', true, date_trunc('day', NOW()) - INTERVAL '156 days' + TIME '11:00', '/uploads/demo/logos/bebidas-costa-este.svg', -34.8425218, -55.9968392) RETURNING id) INSERT INTO _seed_ids SELECT 'D5', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D6'), 'Limpieza Acosta & Cía.', 'Desde 2005 abastecemos a comercios, oficinas e instituciones de Canelones con artículos de limpieza e higiene. Marcas reconocidas y formatos institucionales a precio mayorista. Reparto martes y viernes.', 'Las Piedras, La Paz, Progreso, 18 de Mayo, Colón, Toledo y Pando', 'Av. Sacerdote Luis Pérez Aguirre, Las Piedras, Canelones', true, date_trunc('day', NOW()) - INTERVAL '197 days' + TIME '11:00', '/uploads/demo/logos/limpieza-acosta-cia.svg', -34.7231938, -56.2342369) RETURNING id) INSERT INTO _seed_ids SELECT 'D6', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D7'), 'Almacenera Fernández', 'Distribuidora de almacén con más de 25 años en el Centro y la Aguada. Conservas, enlatados, secos y aceites para almacenes, rotiserías y comedores, con precios especiales por cantidad. Reparto lunes, miércoles y viernes.', 'Centro, Cordón, Aguada, Goes, La Figurita y Jacinto Vera', 'Av. General Flores y Vilardebó, La Figurita, Montevideo', true, date_trunc('day', NOW()) - INTERVAL '162 days' + TIME '11:00', '/uploads/demo/logos/almacenera-fernandez.svg', -34.878, -56.1803) RETURNING id) INSERT INTO _seed_ids SELECT 'D7', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D8'), 'Frío Pereyra Congelados', 'Especialistas en congelados para comercios y gastronomía del este de Montevideo. Hamburguesas, papas, vegetales, pescados y helados con flota refrigerada propia. Pedidos hasta las 18 h para entrega al día siguiente.', 'Carrasco, Carrasco Norte, Punta Gorda, Malvín y Paso Carrasco', 'Camino Carrasco, Carrasco Norte, Montevideo', true, date_trunc('day', NOW()) - INTERVAL '198 days' + TIME '11:00', '/uploads/demo/logos/frio-pereyra-congelados.svg', -34.8703872, -56.0831969) RETURNING id) INSERT INTO _seed_ids SELECT 'D8', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D9'), 'Mayorista Malvín', 'Mayorista de almacén general con depósito en Malvín Norte. Surtido completo de alimentos, bebidas, limpieza y perfumería para autoservicios y almacenes de barrio. Reparto de lunes a sábado.', 'Malvín, Malvín Norte, Buceo, Unión y La Blanqueada', 'Iguá y Boix y Merino, Malvín Norte, Montevideo', true, date_trunc('day', NOW()) - INTERVAL '159 days' + TIME '11:00', '/uploads/demo/logos/mayorista-malvin.svg', -34.882, -56.118) RETURNING id) INSERT INTO _seed_ids SELECT 'D9', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D10'), 'Distribuidora Rodríguez y Silva', 'Distribuidora familiar de golosinas, snacks, galletitas y bebidas para kioscos, almacenes y cantinas escolares de Pando y la Ruta 8. Atención personalizada y reparto semanal fijo por zona.', 'Pando, Barros Blancos, Empalme Olmos, Suárez y Toledo', 'Av. Franklin D. Roosevelt, Pando, Canelones', true, date_trunc('day', NOW()) - INTERVAL '182 days' + TIME '11:00', '/uploads/demo/logos/distribuidora-rodriguez-y-silva.svg', -34.723, -55.958) RETURNING id) INSERT INTO _seed_ids SELECT 'D10', id FROM n;

